import{z as o,x as i,o as r,c as d,q as A,j as B,D as e,d as s,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"功耗分析 DPA","description":"","frontmatter":{"title":"功耗分析 DPA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/power-analysis-dpa.md","filePath":"cs/power-analysis-dpa.md","lastUpdated":1791063341000}'),p={name:"cs/power-analysis-dpa.md"};function D(m,a,P,h,f,u){const t=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="功耗分析-dpa" tabindex="-1">功耗分析 DPA <a class="header-anchor" href="#功耗分析-dpa" aria-label="Permalink to &quot;功耗分析 DPA&quot;">​</a></h1><div class="epigraph"><p>运算的功耗与数据相关时，统计多条曲线就能抽出密钥比特。防护是掩码、随机化与恒定功耗设计，而不是把算法换成「更长的密钥」一句话。</p><footer>—— Kocher, Jaffe and Jun, Differential Power Analysis, CRYPTO 1999</footer></div><p>上一课<a href="/cs/firmware-security">固件</a>还在逻辑更新层面，缺口降到<strong>物理可观测</strong>：功耗。主干侧信道已给时间；本课 DPA。不给采集与分析步骤。<span class="marginnote">SPA 与 DPA 一字之差，问的问题不同：SPA（简单功耗分析）盯着<strong>一条</strong>曲线找结构，好比看一次落笔的笔迹就认出写的是谁；DPA（差分功耗分析）攒<strong>成千上万条</strong>曲线做统计，好比把同一段低语录一万遍再叠加，噪声相互抵消、内容浮出水面。前者怕随机化打乱节奏，后者只能靠压低每一条的相关性来对抗。</span></p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>智能卡、安全元件一旦落到敌手手上，密码算法就只在他的示波器里运行：门电路翻转时充放电，瞬时功耗与翻转的比特相关，而翻转的比特由密钥决定。SPA 读单条曲线，直接看出模幂的平方/乘法序列这类结构；DPA 更进一步：采集多条曲线，按「猜某密钥比特为 1 或 0」分组取均值，猜对时两组在泄漏点出现可统计区分的差值，猜错只剩噪声。因此密钥加长不自动有效——泄漏是逐比特的。缺口是实现对策：掩码把中间值拆成随机份额、隐藏让功耗与数据无关、随机延迟打散对齐——代价是性能与随机数质量。</p><h3 id="实验室模型" tabindex="-1">实验室模型 <a class="header-anchor" href="#实验室模型" aria-label="Permalink to &quot;实验室模型&quot;">​</a></h3><p>课程只要求把功耗标进威胁模型：发出去的设备按「敌手可长期物理接触」评估，而不是只按网络攻击评估。不指导搭建探针。</p><p><span class="marginnote">Kocher et al. 1999。禁止 DPA 实验指导。故障注入下一课是主动物理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把泄漏与对策对应着陈述：哪类运算泄漏——查表、模乘、比较器；哪层对策接——算法层掩码、电路层隐藏、协议层限速与随机化。两者的失败模式不同：掩码怕随机数质量差或份额被单点攻破，隐藏怕工艺偏差让「恒定功耗」假设不成立。下一课故障注入。</p>',11)),(r(),B(n,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E5%AF%86%E9%92%A5%E7%9B%B8%E5%85%B3%E8%BF%90%E7%AE%97%22%5D%20--%3E%20PWR%5B%22%E5%8A%9F%E8%80%97%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20PWR%20--%3E%20STAT%5B%22%E7%BB%9F%E8%AE%A1%E5%8C%BA%E5%88%86%E6%AF%94%E7%89%B9%22%5D%0A%20%20MASK%5B%22%E6%8E%A9%E7%A0%81%E4%B8%8E%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者遇到侧信道的第一反应是「把密钥从 128 位换成 256 位」。这对功耗分析几乎无效——泄漏是逐字节逐比特发生的，攻击者从不面对整把密钥，只面对一个字节里的 256 种猜测，一次攻破一个字节，逐个收网。密钥加长改变的是代数攻击的代价，不改变「每次运算都在发光」这个事实。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"物理层把条件熵泄漏出去：密钥的条件熵随观测次数单调下降，DPA 的分组平均正是把单条曲线里低于噪声的信号累加出来——每条曲线一点微小偏差，上万条叠加就成了清晰峰值。防护核心因此不是「藏住算法」，而是压低每次运算与数据的相关性。与下一课对照：故障注入是主动改计算，DPA 是被动听计算。",-1)),a[6]||(a[6]=E("p",null,"把一个字节的猜测到判定走一遍，就能看清「差分」二字的含义：",-1)),(r(),B(n,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%8C%9C%E6%B5%8B%E7%9B%AE%E6%A0%87%E5%AD%97%E8%8A%82%20%3D%20k%22%5D%20--%3E%20B%5B%22%E6%8C%89%E6%A8%A1%E5%9E%8B%E9%A2%84%E6%B5%8B%E6%AF%8F%E4%B8%AA%E6%97%B6%E5%88%BB%E7%9A%84%E7%BF%BB%E8%BD%AC%E6%AF%94%E7%89%B9%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%8A%8A%E6%9B%B2%E7%BA%BF%E6%8C%89%E9%A2%84%E6%B5%8B%200%2F1%20%E5%88%86%E6%88%90%E4%B8%A4%E7%BB%84%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%B8%A4%E7%BB%84%E5%90%84%E8%87%AA%E6%B1%82%E5%B9%B3%E5%9D%87%E5%86%8D%E7%9B%B8%E5%87%8F%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%87%BA%E7%8E%B0%E6%98%8E%E6%98%BE%E5%B3%B0%E5%80%BC%3F%22%7D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E7%8C%9C%E6%B5%8B%E6%AD%A3%E7%A1%AE%EF%BC%8C%E8%AF%A5%E5%AD%97%E8%8A%82%E6%94%BB%E7%A0%B4%22%5D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20G%5B%22%E6%8D%A2%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%E5%80%BC%E9%87%8D%E6%9D%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">数字实例：统计平均的威力按 \\(\\sqrt N\\) 结账。设单条曲线里泄漏信号幅度为 \\(1\\)、噪声幅度为 \\(100\\)，一条曲线完全淹没；平均 \\(N\\) 条后噪声缩为 \\(100/\\sqrt N\\)——\\(N=10000\\) 时噪声降到 \\(1\\)，信号与噪声打平；\\(N=1000000\\) 时噪声只剩 \\(0.1\\)，峰值清晰可辨。这就是「多采一万条曲线」比「换更强算法」对攻击者更划算的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写探针实验，不评估具体芯片的抗性等级——离开受控实验室这些数字无意义。故障注入下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固件逻辑之后，功耗把数据变成曲线。</li><li>DPA 是统计侧信道；对策是掩码与隐藏。</li><li>密钥加长不自动关功耗泄漏。</li><li>下一课故障注入。</li><li>出处：Kocher, Jaffe and Jun, 1999。</li></ul>',5))])}const _=o(p,[["render",D]]);export{C as __pageData,_ as default};
